import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface ChatMessage {
  role: 'user' | 'model';
  text: string;
}

export enum PricingTier {
  SINGLE = 'SINGLE',
  MONTHLY = 'MONTHLY'
}

import { GoogleGenAI } from "@google/genai";

const apiKey = process.env.API_KEY || '';
const ai = new GoogleGenAI({ apiKey });

export const getRatControlAdvice = async (userQuery: string): Promise<string> => {
  if (!apiKey) {
    return "System Error: API Key missing. Please contact Kola directly.";
  }

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: userQuery,
      config: {
        systemInstruction: `You are the AI Safety Advisor for 'Kola's Rat P Supply' in Tembisa, South Africa.
        Your persona is professional, slightly edgy, and extremely knowledgeable about pest control.
        The business sells rat poison for R15 (single) and R150 (monthly subscription).
        Address: 325 Sedibeng Section, Tembisa. Contact: 0608564191.

        Rules:
        1. Warn users about safety (pets/children) if they ask about usage.
        2. Keep answers short, punchy, and persuasive.
        3. Use a tone that fits a 'black and red' heavy metal aesthetic website.
        4. If the user asks about prices, quote the R15/item and R150/month prices directly.`,
      },
    });

    return response.text || "Connection interrupted. The rats are chewing the cables.";
  } catch (error) {
    console.error("Gemini API Error:", error);
    return "Error connecting to HQ. Call 0608564191 for immediate assistance.";
  }
};

import React, { useEffect, useState, useRef } from 'react';

// Simple SVG Rat Icon
const RatIcon = ({ className }: { className?: string }) => (
  <svg 
    viewBox="0 0 24 24" 
    fill="currentColor" 
    className={className}
    xmlns="http://www.w3.org/2000/svg"
  >
    <path d="M12 2C10.9 2 10 2.9 10 4V6H5C3.9 6 3 6.9 3 8V14C3 15.1 3.9 16 5 16H7V18C7 19.1 7.9 20 9 20H15C16.1 20 17 19.1 17 18V16H19C20.1 16 21 15.1 21 14V8C21 6.9 20.1 6 19 6H14V4C14 2.9 13.1 2 12 2ZM5 8H19V14H5V8ZM9 16H15V18H9V16ZM12 4H14V6H10V4H12Z" fillOpacity="0" />
    <path d="M21.5 13C21.5 13 18 13.5 16 12C15 11.25 15 9 15 9C15 9 13.5 8 11.5 8C9.5 8 8 9 8 9C8 9 8 11.25 7 12C5 13.5 1.5 13 1.5 13" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" fill="none"/>
    <path d="M16 12L22 18M7 12L1 18" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round"/>
    <circle cx="10" cy="10" r="1" fill="red" />
  </svg>
);

const RatAnimation: React.FC = () => {
  const [position, setPosition] = useState({ x: -100, y: 50 });
  const [rotation, setRotation] = useState(0);
  const [isActive, setIsActive] = useState(false);
  const timeoutRef = useRef<NodeJS.Timeout | null>(null);

  const scuttle = () => {
    // Start position (random edge)
    const startSide = Math.random() > 0.5 ? 'left' : 'right';
    const startY = Math.random() * (window.innerHeight - 50);
    const startX = startSide === 'left' ? -100 : window.innerWidth + 100;

    // End position (opposite side)
    const endX = startSide === 'left' ? window.innerWidth + 100 : -100;
    const endY = Math.random() * (window.innerHeight - 50);

    setPosition({ x: startX, y: startY });
    setRotation(startSide === 'left' ? 90 : -90); // Simple rotation logic
    setIsActive(true);

    // Animate across
    const duration = 3000 + Math.random() * 2000; // 3-5 seconds
    const startTime = Date.now();

    const animate = () => {
      const now = Date.now();
      const progress = Math.min((now - startTime) / duration, 1);

      const currentX = startX + (endX - startX) * progress;
      const currentY = startY + (endY - startY) * progress;

      // Add some jitter for realistic scuttling
      const jitterY = Math.sin(progress * 20) * 20;

      setPosition({ x: currentX, y: currentY + jitterY });

      if (progress < 1) {
        requestAnimationFrame(animate);
      } else {
        setIsActive(false);
        scheduleNextScuttle();
      }
    };

    requestAnimationFrame(animate);
  };

  const scheduleNextScuttle = () => {
    const delay = 5000 + Math.random() * 10000; // 5-15 seconds break
    timeoutRef.current = setTimeout(scuttle, delay);
  };

  useEffect(() => {
    scheduleNextScuttle();
    return () => {
      if (timeoutRef.current) clearTimeout(timeoutRef.current);
    };
  }, []);

  if (!isActive) return null;

  return (
    <div 
      className="fixed z-0 pointer-events-none text-neutral-800 opacity-80"
      style={{ 
        left: position.x, 
        top: position.y,
        transform: `rotate(${rotation}deg)`,
        width: '60px',
        height: '60px',
        transition: 'transform 0.1s linear' // Smooth rotation, manual position update
      }}
    >
      <RatIcon className="w-full h-full text-neutral-500 fill-current" />
    </div>
  );
};

export default RatAnimation;

import React, { useState, useRef, useEffect } from 'react';
import { getRatControlAdvice } from '../services/gemini';
import { ChatMessage } from '../types';
import { Send, Bot, X, MessageSquareWarning } from 'lucide-react';

const AiAdvisor: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [messages, setMessages] = useState<ChatMessage[]>([
    { role: 'model', text: "Welcome to Kola's. I'm the automated extermination advisor. Ask me how to use our product safely or about our pricing." }
  ]);
  const [input, setInput] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: "smooth" });
  };

  useEffect(scrollToBottom, [messages]);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!input.trim() || isLoading) return;

    const userMsg = input.trim();
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
    setInput('');
    setIsLoading(true);

    const response = await getRatControlAdvice(userMsg);
    setMessages(prev => [...prev, { role: 'model', text: response }]);
    setIsLoading(false);
  };

  return (
    <div className="fixed bottom-4 right-4 z-50">
      {!isOpen && (
        <button
          onClick={() => setIsOpen(true)}
          className="bg-toxic-red hover:bg-red-700 text-white p-4 rounded-full shadow-[0_0_15px_rgba(255,0,0,0.7)] hover:scale-110 transition-transform animate-bounce"
        >
          <MessageSquareWarning size={32} />
        </button>
      )}

      {isOpen && (
        <div className="bg-neutral-900 border-2 border-toxic-red rounded-lg w-80 md:w-96 h-[500px] flex flex-col shadow-2xl overflow-hidden relative">
          {/* Header */}
          <div className="bg-toxic-red p-3 flex justify-between items-center">
            <h3 className="font-bold font-sans flex items-center gap-2">
              <Bot size={20} />
              AI RAT ADVISOR
            </h3>
            <button onClick={() => setIsOpen(false)} className="hover:text-black">
              <X size={20} />
            </button>
          </div>

          {/* Messages */}
          <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar bg-black/90">
            {messages.map((msg, idx) => (
              <div
                key={idx}
                className={`flex ${msg.role === 'user' ? 'justify-end' : 'justify-start'}`}
              >
                <div
                  className={`max-w-[80%] p-3 rounded-lg text-sm ${
                    msg.role === 'user'
                      ? 'bg-neutral-800 text-white border border-neutral-600'
                      : 'bg-blood-dark/30 text-red-100 border border-toxic-red'
                  }`}
                >
                  {msg.text}
                </div>
              </div>
            ))}
            {isLoading && (
              <div className="flex justify-start">
                <div className="bg-blood-dark/30 p-3 rounded-lg border border-toxic-red">
                  <span className="animate-pulse text-toxic-red">Thinking...</span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input */}
          <form onSubmit={handleSubmit} className="p-3 bg-neutral-900 border-t border-red-900 flex gap-2">
            <input
              type="text"
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Ask about safety..."
              className="flex-1 bg-black border border-red-900 rounded px-3 py-2 text-sm text-white focus:outline-none focus:border-toxic-red"
            />
            <button
              type="submit"
              disabled={isLoading}
              className="bg-toxic-red p-2 rounded hover:bg-red-700 disabled:opacity-50 text-white"
            >
              <Send size={18} />
            </button>
          </form>

          {/* Glitch Overlay Effect */}
          <div className="absolute inset-0 pointer-events-none bg-gradient-to-b from-transparent to-red-900/10 z-0"></div>
        </div>
      )}
    </div>
  );
};

export default AiAdvisor;

